function commitRows(account,map,forceReview){let seen=new Set(D().tx.map(t=>t.fp||fingerprint(t.account,t.date,t.amount,t.desc))),add=[],dups=0,dates=[],source=draft.source||"CSV";draft.rows.forEach(r=>{let get=k=>map[k]>=0?(r[map[k]]||"").trim():"",d=csvDate(get("date")),desc=get("desc"),v=moneyVal(get("amount")),base="",kind=get("type").toLowerCase(),db=Math.abs(moneyVal(get("debit"))),cr=Math.abs(moneyVal(get("credit")));if(db||cr){v=db||cr;base=cr?"income":"expense";}else if(v<0){v=-v;base="expense";}else if(/credit|deposit|inflow|received|refund|income/.test(kind))base="income";else if(/debit|withdraw|outflow|paid|purchase|expense/.test(kind))base="expense";if(!d||!desc||!v)return;dates.push(d);let fp=fingerprint(account,d,v,desc);if(seen.has(fp)){dups++;return;}seen.add(fp);let g=guess(desc,base);if(/transfer/.test(kind))g={type:"transfer",cat:"Transfer",conf:.8,purpose:"Transfer"};let purpose=g.type==="transfer"?"Transfer":g.purpose||(biz()?"Business":"Personal"),purposeSource=g.type==="transfer"?"system":g.purpose?"merchant-rule":"workspace-default";add.push({id:uid("t"),account:account,date:d,desc:desc.slice(0,160),amount:v,type:g.type,cat:g.cat,purpose:purpose,purposeSource:purposeSource,conf:g.conf,status:forceReview||g.conf<.82||g.cat==="Needs sorting"?"review":"confirmed",source:source,file:draft.file,fp:fp});});if(!add.length&&!dups){toast("No rows parsed. Check the mapped columns or use CSV for this statement.","error");return;}D().tx.unshift(...add);if(dates.length){dates.sort();D().imports.push({account:account,start:dates[0],end:dates[dates.length-1],file:draft.file,added:add.length,dups:dups,status:"imported"});}save();let p=add.filter(t=>t.status==="review").length;modal="";draft=null;view="activity";filter=p?"review":"all";render();toast(source==="PDF"?"PDF read locally · "+add.length+" added, "+p+" to review":add.length+" added · "+dups+" duplicates skipped · "+p+" to review");}
function learn(t,cat,type,purpose){let explicitPurpose=purpose!==undefined&&purpose!==null&&purpose!=="",chosen=type==="transfer"?"Transfer":purpose||t.purpose||(type==="transfer"?"Transfer":biz()?"Business":"Personal");t.cat=cat;t.type=type;t.purpose=chosen;if(explicitPurpose)t.purposeSource="user";t.status=cat==="Needs sorting"||t.purpose==="Needs sorting"?"review":"confirmed";let k=merchant(t.desc),updated=0;if(k&&cat!=="Needs sorting"){D().rules=D().rules.filter(r=>r.key!==k);let rule={key:k,cat:cat,type:type};if(explicitPurpose)rule.purpose=chosen;D().rules.unshift(rule);D().tx.forEach(o=>{if(o.id===t.id||merchant(o.desc)!==k)return;o.cat=cat;o.type=type;if(explicitPurpose&&(o.purposeSource==="workspace-default"||o.purpose==="Needs sorting")){o.purpose=chosen;o.purposeSource="merchant-rule";}o.status=o.cat==="Needs sorting"||o.purpose==="Needs sorting"?"review":"confirmed";updated++;});}return updated;}
